// Clean the model output and re-emit it in the shape the parent workflow reads
// ($json.output[0].content[0].text), so ContentGeneration3.0 needs no change.

let text = $json.output?.[0]?.content?.[0]?.text;
if (!text) throw new Error("No model output at output[0].content[0].text");

text = text.trim();

// Strip markdown fences and any wrapping quotes
text = text.replace(/^```[a-z]*\s*/i, "").replace(/\s*```$/, "").trim();
if (/^["'\u201c].*["'\u201d]$/s.test(text)) text = text.slice(1, -1).trim();

// Strip a leading preamble line ("Here is your story:", "Certainly!", a title)
const lines = text.split("\n");
if (lines.length > 1 && /^(here|sure|certainly|okay|of course|title)\b/i.test(lines[0].trim())) {
  lines.shift();
  text = lines.join("\n").trim();
}

// Normalise typography. Smart quotes and dashes reach edge-tts and the ASS
// subtitle file; ASCII is safer in both.
text = text
  .replace(/[\u2018\u2019\u201b]/g, "'")
  .replace(/[\u201c\u201d]/g, '"')
  .replace(/[\u2013\u2014]/g, " - ")
  .replace(/\u2026/g, "...")
  .replace(/[ \t]+/g, " ")
  .replace(/\n{2,}/g, "\n\n")
  .trim();

const words = text.split(/\s+/).filter(Boolean).length;

// Surfaced for debugging, not enforced. A hard retry loop is not worth the extra
// generation time when 120-200 words is 32-54 seconds either way.
const flagged = ["chill", "spine", "dread", "eerie", "unsettling", "realized", "realised",
   "as if", "wrong", "seemed", "somehow"]
  .filter(w => new RegExp("\\b" + w, "i").test(text));

return [{ json: {
  output: [{ content: [{ text }] }],   // parent-compatible shape
  wordCount: words,
  estimatedSeconds: +(words / 3.72).toFixed(1),
  flaggedWords: flagged,
  brief: $('Randomizer').item.json.decisions
} }];
